import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const i=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"掩码寄存器计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/mask_reg_compute/mask_reg_compute"},{"text":"mask使用说明","link":"/api/SIMD-API/tensor_api/reg_vector_compute/mask_reg_compute/mask_usage"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/mask_reg_compute/mask_usage.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/mask_reg_compute/mask_usage.md","outlineHeaders":[{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"初始化mask","slug":"初始化mask","link":"#初始化mask"},{"level":3,"title":"与load链式调用","slug":"与load链式调用","link":"#与load链式调用"},{"level":2,"title":"计算接口中的mask传递","slug":"计算接口中的mask传递","link":"#计算接口中的mask传递"},{"level":2,"title":"特殊接口说明","slug":"特殊接口说明","link":"#特殊接口说明"}],"lastUpdated":1788319986000}'),e={name:"api/SIMD-API/tensor_api/reg_vector_compute/mask_reg_compute/mask_usage.md"};function l(o,s,t,d,r,m){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>mask的用法</h1><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p><code>reg_tensor&lt;DataType&gt;</code>同时保存数据寄存器<code>reg</code>和与数据关联的掩码寄存器<code>mask</code>。计算接口根据输入<code>reg_tensor</code>的<code>mask</code>选择参与计算的有效元素，并将计算所使用的mask传递给返回的<code>reg_tensor</code>。<code>local_tensor::store</code>的单源<code>direct</code>、<code>pack</code>和<code>pack_quarter</code>模式继续使用源<code>reg_tensor</code>中保存的mask控制写回。</p><p><code>reg_tensor</code>的默认构造函数不初始化<code>reg</code>和<code>mask</code>。作为计算接口的输入参数前，必须保证其<code>mask</code>已初始化；否则，参与计算和写回的有效元素不确定。若计算链中的有效范围发生变化，应在下一次计算或写回前重新调用<code>with_mask</code>绑定新的mask。</p><p>当<code>DataType</code>为<code>bool</code>时，<code>reg_tensor&lt;bool&gt;</code>同样包含<code>reg</code>和<code>mask</code>两个成员。<code>all_mask</code>、<code>make_mask</code>、<code>update_mask</code>及比较接口只保证返回对象的<code>reg</code>成员有效，不应直接读取其<code>mask</code>成员。</p><h2 id="初始化mask">初始化mask<a class="header-anchor" href="#初始化mask">​</a></h2><p>可通过以下接口生成mask，类型为<code>reg_tensor&lt;bool&gt;</code>：</p><table><thead><tr><th>接口</th><th>使用场景</th></tr></thead><tbody><tr><td><code>all_mask&lt;DataType&gt;()</code></td><td>当前寄存器中的所有元素都有效。</td></tr><tr><td><code>make_mask&lt;Pattern, DataType&gt;()</code></td><td>按固定模式生成mask。</td></tr><tr><td><code>update_mask&lt;DataType&gt;(remain)</code></td><td>按剩余元素数量生成mask，通常用于处理循环中的尾块。</td></tr></tbody></table><p><code>DataType</code>必须与mask所服务的数据元素类型保持一致。例如，在给<code>reg_tensor&lt;float&gt;</code>赋值时应使用<code>all_mask&lt;float&gt;()</code>或<code>update_mask&lt;float&gt;(remain)</code>，不同元素位宽对应的有效元素数不同。</p><h3 id="与load链式调用">与load链式调用<a class="header-anchor" href="#与load链式调用">​</a></h3><p><code>load</code>和<code>load_broadcast</code>只初始化返回对象的<code>reg</code>，不初始化<code>mask</code>。推荐通过链式计算<code>with_mask</code>或在搬入后立即绑定mask：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">auto</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">update_mask</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="n">remain</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">src0Reg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="p">(</span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="n">offset</span><span class="p">)).</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">src1Reg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="p">(</span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="n">offset</span><span class="p">)).</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>
</code></pre></div><p>对于返回<code>reg_pair</code>的<code>deintlv</code>搬入模式，需分别为两个成员绑定mask：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">auto</span><span class="w"> </span><span class="n">srcReg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load_sideband_mode</span><span class="o">::</span><span class="n">deintlv</span><span class="o">&gt;</span><span class="p">(</span>
<span class="w">    </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="n">offset</span><span class="p">));</span>

<span class="k">auto</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">all_mask</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="p">();</span>
<span class="n">srcReg</span><span class="p">.</span><span class="n">first</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>
<span class="n">srcReg</span><span class="p">.</span><span class="n">second</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>
</code></pre></div><h2 id="计算接口中的mask传递">计算接口中的mask传递<a class="header-anchor" href="#计算接口中的mask传递">​</a></h2><p>常规计算接口使用以下规则：</p><table><thead><tr><th>计算形式</th><th>计算使用的mask</th><th>返回的<code>dst_reg_tensor.mask</code></th></tr></thead><tbody><tr><td>单输入，例如<code>abs(src)</code>、<code>exp(src)</code>、<code>cast&lt;DstType&gt;(src)</code></td><td><code>src.mask</code></td><td>与<code>src.mask</code>保持一致。</td></tr><tr><td>一个<code>reg_tensor</code>与标量计算，例如<code>src + scalar</code>、<code>scalar * src</code></td><td><code>reg_tensor</code>操作数的<code>mask</code></td><td>与该<code>reg_tensor</code>的<code>mask</code>保持一致。</td></tr><tr><td>多个<code>reg_tensor</code>计算，例如<code>src0 + src1</code>、<code>fma(src0, src1, src2)</code></td><td>第一个<code>reg_tensor</code>操作数的<code>mask</code></td><td>与第一个<code>reg_tensor</code>操作数的<code>mask</code>保持一致。</td></tr><tr><td>带输出参数，例如<code>add(carry, src0, src1)</code>、<code>mull(high, src0, src1)</code></td><td><code>src0.mask</code></td><td>返回值以及<code>carry</code>或<code>high</code>的<code>mask</code>均与<code>src0.mask</code>保持一致。</td></tr><tr><td>显式传入mask，例如<code>fill(value, mask)</code></td><td><code>mask.reg</code></td><td>与显式传入的<code>mask.reg</code>保持一致。</td></tr></tbody></table><p>对于多个<code>reg_tensor</code>输入，接口不会合并或校验各输入的mask，第二个及后续输入的<code>reg_tensor</code>的<code>mask</code>不参与确定有效元素。调用前应保证所有数据输入的mask与第一个<code>reg_tensor</code>操作数保持一致。例如：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">auto</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">update_mask</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="n">remain</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">src0Reg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="p">(</span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="n">offset</span><span class="p">)).</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">src1Reg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="p">(</span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="n">offset</span><span class="p">)).</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>

<span class="k">auto</span><span class="w"> </span><span class="n">dstReg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src0Reg</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">src1Reg</span><span class="p">;</span>
<span class="c1">// dstReg.mask与src0Reg.mask保持一致，可直接用于单源store。</span>
<span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">store</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="n">offset</span><span class="p">),</span><span class="w"> </span><span class="n">dstReg</span><span class="p">);</span>
</code></pre></div><h2 id="特殊接口说明">特殊接口说明<a class="header-anchor" href="#特殊接口说明">​</a></h2><ul><li><code>deinterleave</code>等重排接口可能重新生成输出mask，不遵循普通多输入计算的传递规则，具体以对应接口说明为准。</li></ul></article></div>`,1)])])}const _=a(e,[["render",l]]);export{i as __pageData,_ as default};
